const form = $input.first().json;
const rawType = form['Broadcast Type'] || '';
const isDelay = rawType.startsWith('Delay Alert');

const channelStr = form['Promo Channels'] || 'SMS and Email';
let channels = ['sms', 'email'];
if (channelStr === 'SMS only')   channels = ['sms'];
if (channelStr === 'Email only') channels = ['email'];

return [{
  json: {
    is_delay: isDelay,
    sms_message:   form['SMS Message'] || '',
    email_subject: form['Email Subject'] || '',
    email_body:    form['Email Body (HTML)'] || '',
    target_date:   form['Affected Date (for Delay Alert, leave blank for today)'] || null,
    promo_title:   form['Promo Title (for Promotional Blast only)'] || 'Promotional Blast',
    channels,
    created_by:    form['Your Name'] || null,
  }
}];

// Build confirmation message for delay alert
const resp = $input.first().json;
const ok   = resp.status === 'queued';
const msg  = ok
  ? `✅ Delay alert queued!\n\nJob ID: ${resp.job_id}\nDate: ${resp.target_date}\nRecipients: ${resp.total_recipients}\n\nSMS and email will be dispatched within 5 minutes.`
  : `❌ Error: ${JSON.stringify(resp)}`;
return [{ json: { result_message: msg } }];

// Build confirmation message for promo blast
const queueResp  = $input.first().json;
const createResp = $('Create Promo Job').first().json;
const ok = queueResp.status === 'queued';
const msg = ok
  ? `✅ Promotional blast queued!\n\nJob ID: ${createResp.job_id}\nRecipients: ${queueResp.total_recipients}\n\nMessages will be dispatched in batches every 5 minutes.`
  : `❌ Error: ${JSON.stringify(queueResp)}`;
return [{ json: { result_message: msg } }];
